1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Badge } from "@/components/ui/badge";
14	import { Button } from "@/components/ui/button";
15	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
16	import { format } from "date-fns";
17	import { toast } from "sonner";
18	import OnboardingWizard from "@/components/OnboardingWizard";
19	
20	export interface PastJob {
21	  id: string;
22	  title: string | null;
23	  job_description: string;
24	  status: string;
25	  created_at: string;
26	  resume_count: number;
27	  jd_analysis_json: any;
28	  dynamic_weights_json: Record<string, number> | null;
29	  inbox_email: string | null;
30	}
31	
32	export interface Result {
33	  id: string;
34	  resume_id: string;
35	  overall_score: number;
36	  missing_skills: string[];
37	  summary: string | null;
38	  interview_questions: any;
39	  filename: string;
40	  file_path: string | null;
41	  candidate_name: string | null;
42	  candidate_email?: string | null;
43	  candidate_phone?: string | null;
44	  candidate_location?: string | null;
45	  // Dynamic scoring fields
46	  hard_fit?: boolean;
47	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
48	  confidence?: number;
49	  strengths_json?: string[];
50	  gaps_json?: string[];
51	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
52	  matched_must_haves?: string[];
53	  missing_must_haves?: string[];
54	  scoring_version?: string;
55	  pending?: boolean;
56	  parsed_json?: any;
57	  assigned_to?: string | null;
58	}
59	
60	export interface ExistingResume {
61	  id: string;
62	  filename: string;
63	  file_path: string | null;
64	  candidate_name: string | null;
65	  created_at: string;
66	}
67	
68	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
69	
70	const ONBOARDING_KEY = "rankora_onboarding_done";
71	
72	const Index = () => {
73	  const { user, profile } = useAuth();
74	  const [searchParams, setSearchParams] = useSearchParams();
75	  const location = useLocation();
76	  const navigate = useNavigate();
77	
78	  // Show onboarding wizard for first-time users
79	  const [showOnboarding, setShowOnboarding] = useState(() => {
80	    if (typeof window === "undefined") return false;
81	    return !localStorage.getItem(ONBOARDING_KEY);
82	  });
83	
84	  const completeOnboarding = useCallback(() => {
85	    localStorage.setItem(ONBOARDING_KEY, "1");
86	    setShowOnboarding(false);
87	  }, []);
88	
89	  const queryClient = useQueryClient();
90	
91	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
92	    queryKey: ["pastJobs", user?.id],
93	    queryFn: async () => {
94	      const { data: jobs } = await supabase
95	        .from("jobs")
96	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
97	        .eq("user_id", user!.id)
98	        .order("created_at", { ascending: false })
99	        .limit(50);
100	      if (!jobs) return [];
101	      return jobs.map((j: any) => ({
102	        id: j.id,
103	        title: j.title,
104	        job_description: j.job_description,
105	        status: j.status,
106	        created_at: j.created_at,
107	        resume_count: j.resumes?.[0]?.count ?? 0,
108	        jd_analysis_json: j.jd_analysis_json,
109	        dynamic_weights_json: j.dynamic_weights_json,
110	        inbox_email: j.inbox_email ?? null,
111	      })) as PastJob[];
112	    },
113	    enabled: !!user,
114	    staleTime: 2 * 60 * 1000,
115	  });
116	
117	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
118	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
119	  const [results, setResults] = useState<Result[]>([]);
120	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
121	  const [authOpen, setAuthOpen] = useState(false);
122	
123	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
124	
125	  // Sync view with route path
126	  useEffect(() => {
127	    if (location.pathname === "/jobs") {
128	      setView("my-jobs");
129	      setSelectedJobId(null);
130	    }
131	  }, [location.pathname]);
132	
133	  // Handle URL params for deep linking
134	  useEffect(() => {
135	    const jobParam = searchParams.get("job");
136	    const newParam = searchParams.get("new");
137	
138	    if (jobParam && user) {
139	      loadJobData(jobParam);
140	      setSearchParams({}, { replace: true });
141	    } else if (newParam && user) {
142	      handleNewJob();
143	      setSearchParams({}, { replace: true });
144	    }
145	    // eslint-disable-next-line react-hooks/exhaustive-deps
146	  }, [searchParams, user]);
147	
148	  const loadJobData = async (jobId: string) => {
149	    setSelectedJobId(jobId);
150	    setView("job-detail");
151	    try {
152	      // Single query for all resume data (was 2 separate queries)
153	      const { data: allResumes } = await supabase
154	        .from("resumes")
155	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
156	        .eq("job_id", jobId)
157	        .order("created_at", { ascending: false });
158	
159	      const resumeData = allResumes ?? [];
160	      setExistingResumes(resumeData.map((r) => ({
161	        id: r.id, filename: r.filename, file_path: r.file_path,
162	        candidate_name: r.candidate_name, created_at: r.created_at,
163	      })));
164	
165	      if (resumeData.length === 0) {
166	        setResults([]);
167	        return;
168	      }
169	
170	      const resumeIds = resumeData.map((r) => r.id);
171	      const { data: resultData } = await supabase
172	        .from("results")
173	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
174	        .in("resume_id", resumeIds);
175	
176	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
177	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
178	        const resume = resumeMap.get(r.resume_id);
179	        const parsed = resume?.parsed_json as any;
180	        return {
181	          ...r,
182	          overall_score: r.overall_score ?? 0,
183	          missing_skills: r.missing_skills ?? [],
184	          filename: resume?.filename ?? "Unknown",
185	          file_path: resume?.file_path ?? null,
186	          candidate_name: resume?.candidate_name ?? null,
187	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
188	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
189	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
190	          parsed_json: resume?.parsed_json ?? null,
191	        };
192	      });
193	      // Deduplicate by resume_id — keep highest scoring result per resume
194	      const deduped = new Map<string, Result>();
195	      for (const r of allMerged) {
196	        const existing = deduped.get(r.resume_id);
197	        if (!existing || r.overall_score > existing.overall_score) {
